mapper.insert:
INSERT INTO notification_setting (
    member_id, performance_shortage_enabled, benefit_limit_enabled
) VALUES (
             #{setting.memberId}, #{setting.performanceShortageEnabled}, #{setting.benefitLimitEnabled}
         )
    ON DUPLICATE KEY UPDATE
                         performance_shortage_enabled = VALUES(performance_shortage_enabled),
                         benefit_limit_enabled = VALUES(benefit_limit_enabled)

mapper.select:
SELECT notification_id, notification_type, title, content, created_at, read_at
FROM notification
WHERE member_id = #{memberId}
  AND deleted_at IS NULL
ORDER BY created_at DESC, notification_id DESC
    LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE notification
SET read_at = NOW()
WHERE notification_id = #{notificationId}
  AND member_id = #{memberId}
  AND deleted_at IS NULL
  AND read_at IS NULL

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM notification
    WHERE notification_id = #{notificationId}
      AND member_id = #{memberId}
      AND deleted_at IS NULL
)

mapper.update:
UPDATE notification
SET deleted_at = NOW()
WHERE notification_id = #{notificationId}
  AND member_id = #{memberId}
  AND deleted_at IS NULL

mapper.select:
SELECT n.member_id, n.deduplication_key FROM notification n JOIN (
SELECT #{lookup.memberId} AS member_id, #{lookup.deduplicationKey} AS deduplication_key
) target ON target.member_id = n.member_id AND target.deduplication_key = n.deduplication_key
